def improve(weights, edges, stages, depth, ratio):
    import random, time, bisect
    end = time.perf_counter() + 8.6
    n = len(weights)
    best = list(stages)
    if n < 2 or depth < 2:
        return best
    s = best[:]
    pre = [[] for _ in s]
    post = [[] for _ in s]
    coef = [0]*n
    for u,v,w in edges:
        if u != v:
            pre[v].append(u)
            post[u].append(v)
            coef[u] -= w
            coef[v] += w
    loads = [0]*depth
    for u,w in enumerate(weights):
        loads[s[u]] += w
    comm = sum(c*t for c,t in zip(coef,s))
    peak = max(loads)
    sq = sum(x*x for x in loads)
    value = ratio*peak+comm
    pending = {}
    rng = random.Random(71)
    tick = 0
    left = 8.6
    tops = sorted(range(depth), key=loads.__getitem__, reverse=True)[:3]
    while True:
        if tick % 128 == 0:
            left = end-time.perf_counter()
            if left <= 0:
                break
        if tick % 2048 == 0:
            groups = [[] for _ in loads]
            for u,w in enumerate(weights):
                groups[s[u]].append((w,u))
            for g in groups:
                g.sort()
        tick += 1
        direct = left < 2.8 or 3.7 < left < 5.5 or ratio <= 0
        def key(p,q,c):
            return (ratio*p+c,q) if direct else (p,q,c)
        cur = key(peak,sq,comm)
        chosen = None
        u = rng.randrange(n)
        if tick % 4 == 0:
            g = groups[tops[0]]
            if g:
                u = g[rng.randrange(len(g))][1]
        a = s[u]
        wu = weights[u]
        lo = max((s[v] for v in pre[u]), default=0)
        hi = min((s[v] for v in post[u]), default=depth-1)
        trials = [(b,-1) for b in range(lo,hi+1) if b != a]
        b = rng.randrange(depth)
        if tick % 3 == 0:
            b = min(range(depth), key=loads.__getitem__)
        if b != a and lo <= b <= hi:
            g = groups[b]
            if g:
                for target in (wu+(loads[b]-loads[a])//2, wu):
                    j = bisect.bisect_left(g,(target,-1))
                    for off in (0,-1,rng.randrange(-8,9)):
                        k = j+off
                        if 0 <= k < len(g):
                            v = g[k][1]
                            if s[v] == b:
                                trials.append((b,v))
        for b,v in trials:
            delta = (weights[v] if v >= 0 else 0)-wu
            x,y = loads[a]+delta,loads[b]-delta
            other = next((loads[t] for t in tops if t != a and t != b),0)
            p = max(x,y,other)
            q = sq+x*x+y*y-loads[a]**2-loads[b]**2
            c = comm+(coef[u]-(coef[v] if v >= 0 else 0))*(b-a)
            k = key(p,q,c)
            if k >= cur:
                continue
            if v >= 0:
                if any((a if t == v else s[t]) > b for t in pre[u]):
                    continue
                if any((a if t == v else s[t]) < b for t in post[u]):
                    continue
                if any((b if t == u else s[t]) > a for t in pre[v]):
                    continue
                if any((b if t == u else s[t]) < a for t in post[v]):
                    continue
            cur = k
            chosen = b,v,p,q,c,x,y
        if chosen is None:
            continue
        b,v,peak,sq,comm,x,y = chosen
        loads[a],loads[b] = x,y
        s[u] = b
        pending[u] = b
        if v >= 0:
            s[v] = a
            pending[v] = a
        tops = sorted(range(depth),key=loads.__getitem__,reverse=True)[:3]
        obj = ratio*peak+comm
        if obj < value:
            for u,b in pending.items():
                best[u] = b
            pending.clear()
            value = obj
    return best
